          '**النموذج الافتراضي:** يختار `auto` النموذج `tiny-int8` على أجهزة ARM مثل Raspberry Pi 4 و`base-int8` في غيرها؛ والنسخ `-int8` أقل دقة بقليل لكنها أصغر وأسرع ([توثيق تطبيق Whisper](https://github.com/home-assistant/addons/blob/master/whisper/DOCS.md)).',
