          'Whisper 앱은 `turbo`(`large-v3`보다 빠름)와 `distil-small.en` 같은 영어 전용 증류 모델도 제공합니다([Whisper 앱 문서](https://github.com/home-assistant/addons/blob/master/whisper/DOCS.md)).',
