        content:
          '**MacWhisper는 Mac 데스크톱 앱이며 Home Assistant 구성 요소가 아닙니다. Assist에는 Whisper 앱이나 다른 Wyoming 음성→텍스트 서버를 사용하세요.** [MacWhisper](https://www.macwhisper.com)는 오디오, 영상, 회의, 시스템 오디오를 Mac에서 로컬로 변환하는 앱이며, 공식 사이트에는 Home Assistant나 Wyoming 프로토콜에 대한 언급이 없습니다.',
